// Simple endless side‑scroll game for canvas with id "game"
(function(){
  const canvas = document.getElementById('game');
  if(!canvas) return; // canvas must exist
  const ctx = canvas.getContext('2d');
  const w = canvas.width = canvas.offsetWidth || 800;
  const h = canvas.height = canvas.offsetHeight || 400;
  // player ship
  const ship = {x:50, y:h/2-15, w:30, h:30, dy:0, speed:3};
  // asteroid pool
  const asteroids=[];
  let frame=0, score=0, gameOver=false;
  // keyboard handling
  const keys={};
  window.addEventListener('keydown',e=>keys[e.key]=true);
  window.addEventListener('keyup',e=>keys[e.key]=false);
  function spawn(){
    const size = 20+Math.random()*30;
    asteroids.push({x:w, y:Math.random()*(h-size), w:size, h:size, speed:2+Math.random()*3});
  }
  function update(){
    if(gameOver) return;
    // move ship
    if(keys['ArrowUp']) ship.y-=ship.speed;
    if(keys['ArrowDown']) ship.y+=ship.speed;
    if(keys['ArrowLeft']) ship.x-=ship.speed;
    if(keys['ArrowRight']) ship.x+=ship.speed;
    ship.y = Math.max(0, Math.min(h-ship.h, ship.y));
    ship.x = Math.max(0, Math.min(w-ship.w, ship.x));
    // spawn asteroids
    if(frame%60===0) spawn();
    // move asteroids
    for(let i=asteroids.length-1;i>=0;i--){
      const a=asteroids[i];
      a.x-=a.speed;
      // remove off‑screen
      if(a.x+a.w<0) {asteroids.splice(i,1); score++;}
      // collision check
      if(a.x < ship.x+ship.w && a.x+a.w > ship.x && a.y < ship.y+ship.h && a.y+a.h > ship.y){
        gameOver=true;
      }
    }
    frame++;
  }
  function draw(){
    ctx.clearRect(0,0,w,h);
    // draw ship
    ctx.fillStyle='cyan';
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // draw asteroids
    ctx.fillStyle='gray';
    asteroids.forEach(a=>ctx.fillRect(a.x, a.y, a.w, a.h));
    // draw score
    ctx.fillStyle='white';
    ctx.font='16px sans-serif';
    ctx.fillText('Score: '+score,10,20);
    if(gameOver){
      ctx.fillStyle='red';
      ctx.font='30px sans-serif';
      ctx.fillText('Game Over', w/2-80, h/2);
    }
  }
  function loop(){
    update();
    draw();
    if(!gameOver) requestAnimationFrame(loop);
  }
  loop();
})();
